import { validateToolArgs } from "./agent/toolValidation";

const tool = toolRegistry.get(toolName);
if (!tool) {
  throw TemplateError.user("TOOL_UNKNOWN", `Unknown tool: ${toolName}`, {
    tool_name: toolName,
    available_tools: toolRegistry.listNames().slice(0, 20),
  });
}

const validation = validateToolArgs(tool.schema, toolArgs);
if (!validation.ok) {
  throw TemplateError.user(
    "TOOL_ARGS_INVALID",
    `Tool arguments did not match schema for ${tool.name}: ${validation.summary}`,
    { tool_name: tool.name, schema_errors: validation.errors }
  );
}

return await tool.handler(toolArgs);
```
